use crate::parser::{FunctionControl, KeyAction, Keys, Row, Script};
use std::{
    collections::{BTreeMap, BTreeSet},
    error::Error,
    fmt,
};

#[derive(Debug, PartialEq, Eq)]
pub struct KeyFrame {
    /// One-based input line, including for ticks generated by a wait.
    pub line: usize,
    pub held: BTreeSet<String>,
    pub pressed: BTreeSet<String>,
    pub released: BTreeSet<String>,
}

/// Keep one instance for successive blocks in a game session.
#[derive(Default)]
pub struct Keyboard {
    persistent: BTreeSet<String>,
    held: BTreeSet<String>,
}

/// The fixed-tick keyboard preview cannot evaluate function control.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PreviewError;

impl fmt::Display for PreviewError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("a script with FUNCTION or RETURN requires game playback")
    }
}

impl Error for PreviewError {}

impl Keyboard {
    /// Project the fixed ticks of a script onto the keyboard. Dynamic mouse waits
    /// depend on game state; this keyboard-only preview treats them as already idle.
    /// Game playback uses `Script::compile` to preserve those waits.
    ///
    /// # Panics
    ///
    /// Panics when the script defines functions or contains `RETURN`. Use
    /// [`Keyboard::try_play`] to handle unsupported scripts as an error.
    #[track_caller]
    pub fn play<'a>(&'a mut self, script: &'a Script) -> impl Iterator<Item = KeyFrame> + 'a {
        self.try_play(script)
            .unwrap_or_else(|error| panic!("{error}"))
    }

    /// Preview fixed ticks or report that the script requires game playback.
    pub fn try_play<'a>(
        &'a mut self,
        script: &'a Script,
    ) -> Result<impl Iterator<Item = KeyFrame> + 'a, PreviewError> {
        if script.uses_functions() {
            return Err(PreviewError);
        }
        Ok(script
            .rows
            .iter()
            .flat_map(|row| {
                let waiting = (0..row.wait).map(move |_| (row.line, None));
                let input = row.has_input().then_some((row.line, Some(&row.keys)));
                waiting.chain(input)
            })
            .map(|(line, keys)| self.step(line, keys)))
    }

    fn step(&mut self, line: usize, keys: Option<&Keys>) -> KeyFrame {
        let mut held = self.persistent.clone();
        if let Some(keys) = keys {
            for (key, action) in keys {
                match action {
                    KeyAction::Temporary => {
                        held.insert(key.clone());
                    }
                    KeyAction::Press => {
                        self.persistent.insert(key.clone());
                        held.insert(key.clone());
                    }
                    KeyAction::Release => {
                        self.persistent.remove(key);
                        held.remove(key);
                    }
                }
            }
        }
        let pressed = held.difference(&self.held).cloned().collect();
        let released = self.held.difference(&held).cloned().collect();
        self.held.clone_from(&held);
        KeyFrame {
            line,
            held,
            pressed,
            released,
        }
    }
}

/// A fixed input run or a zero-tick control operation for game-side evaluation.
#[derive(Default, Debug)]
pub struct KeyRun {
    pub key_actions: BTreeMap<String, &'static str>,
    pub source: String,
    pub pause: bool,
    pub handler: Option<(String, Vec<KeyRun>)>,
    pub screenshot: Option<String>,
    pub clear_listeners: bool,
    pub moves: Vec<serde_json::Value>,
    pub buttons: BTreeMap<String, &'static str>,
    pub wait_mouse: bool,
    pub clear: bool,
    pub line: usize,
    pub ticks: u64,
    /// Full key state for legacy playback. The game queue applies `key_actions`.
    pub held: BTreeSet<String>,
    pub control: Option<FunctionControl>,
}

pub struct DispatchProgram {
    pub runs: Vec<KeyRun>,
    /// Function names without the leading `$`, mapped to their compiled bodies.
    pub functions: BTreeMap<String, Vec<KeyRun>>,
    /// Final key state for legacy playback. The game queue tracks held keys at runtime.
    pub persistent: BTreeSet<String>,
    /// Includes release-only names, so all bindings can be validated before playback.
    pub keys: BTreeMap<String, usize>,
}

fn wire_actions(actions: &Keys) -> BTreeMap<String, &'static str> {
    actions
        .iter()
        .map(|(name, action)| {
            let value = match action {
                KeyAction::Temporary => "temporary",
                KeyAction::Press => "press",
                KeyAction::Release => "release",
            };
            (name.clone(), value)
        })
        .collect()
}

impl Script {
    /// Source of a key sent for game-side validation in a multi-file submission.
    pub fn key_location(&self, key: &str) -> Option<(&str, usize)> {
        self.import_keys
            .get(key)
            .map(|(source, line)| (source.as_str(), *line))
    }

    pub fn compile(&self, persistent: BTreeSet<String>) -> DispatchProgram {
        let mut keys = BTreeMap::new();
        let mut keyboard = Keyboard {
            persistent,
            held: BTreeSet::new(),
        };
        let runs = compile_block(&self.rows, &mut keyboard, &mut keys);
        let functions = self
            .functions
            .iter()
            .map(|(name, rows)| {
                (
                    name.clone(),
                    compile_block(rows, &mut Keyboard::default(), &mut keys),
                )
            })
            .collect();
        // Imported entry blocks are checked even though their runs are never dispatched.
        for (key, (_, line)) in &self.import_keys {
            keys.insert(key.clone(), *line);
        }
        DispatchProgram {
            runs,
            functions,
            persistent: keyboard.persistent,
            keys,
        }
    }
}

fn compile_block(
    rows: &[Row],
    keyboard: &mut Keyboard,
    keys: &mut BTreeMap<String, usize>,
) -> Vec<KeyRun> {
    let mut runs = Vec::new();
    for row in rows {
        for key in row.keys.keys() {
            keys.entry(key.clone())
                .and_modify(|line| *line = (*line).min(row.line))
                .or_insert(row.line);
        }
        if let Some((event, body)) = &row.handler {
            runs.push(KeyRun {
                line: row.line,
                source: format!("ON({event})"),
                handler: Some((
                    event.clone(),
                    compile_block(body, &mut Keyboard::default(), keys),
                )),
                ..Default::default()
            });
        }
        if row.clear_listeners || row.screenshot.is_some() || row.control.is_some() {
            runs.push(KeyRun {
                line: row.line,
                source: if row.clear_listeners {
                    "CLEAR_LISTENERS".into()
                } else {
                    row.input_source.clone()
                },
                clear_listeners: row.clear_listeners,
                screenshot: row.screenshot.clone(),
                control: row.control.clone(),
                ..Default::default()
            });
        }
        if row.wait > 0 || row.wait_mouse || row.clear {
            runs.push(KeyRun {
                line: row.line,
                source: if row.clear {
                    "CLEAR".into()
                } else if row.wait_mouse {
                    "WaitMouseMove()".into()
                } else {
                    format!("Wait({})", row.wait)
                },
                ticks: row.wait,
                held: keyboard.persistent.clone(),
                wait_mouse: row.wait_mouse,
                clear: row.clear,
                ..KeyRun::default()
            });
        }
        if row.has_input() {
            runs.push(KeyRun {
                line: row.line,
                ticks: 1,
                held: keyboard.step(row.line, Some(&row.keys)).held,
                source: row.input_source.clone(),
                moves: row.moves.clone(),
                buttons: wire_actions(&row.buttons),
                key_actions: wire_actions(&row.keys),
                ..KeyRun::default()
            });
        }
        if row.pause {
            runs.push(KeyRun {
                line: row.line,
                source: "PAUSE".into(),
                pause: true,
                ..KeyRun::default()
            });
        }
    }
    runs
}

#[cfg(test)]
mod dispatch_tests {
    use super::*;

    #[test]
    fn compile_preserves_waits_and_transfers_without_replaying_prior_ticks() {
        let script =
            Script::parse("BEGIN\nWait(4294967296) Key(w)\nKeyPress(w) KeyRelease(a)\nEND")
                .unwrap();
        let program = script.compile(BTreeSet::from(["a".to_owned()]));
        assert_eq!(program.runs.len(), 3);
        assert_eq!(program.runs[0].ticks, 4294967296);
        assert_eq!(program.runs[0].held, BTreeSet::from(["a".to_owned()]));
        assert_eq!(program.runs[1].held.len(), 2);
        assert_eq!(program.persistent, BTreeSet::from(["w".to_owned()]));
        assert!(program.keys.contains_key("a"));
    }
}
